import{_ as s,H as e,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"06 | PromQL有哪些常见的使用场景？","description":"","frontmatter":{},"headers":[{"level":2,"title":"时序数据","slug":"时序数据","link":"#时序数据","children":[]},{"level":2,"title":"PromQL 典型的应用场景","slug":"promql-典型的应用场景","link":"#promql-典型的应用场景","children":[{"level":3,"title":"查询选择器","slug":"查询选择器","link":"#查询选择器","children":[]},{"level":3,"title":"算术运算符","slug":"算术运算符","link":"#算术运算符","children":[]},{"level":3,"title":"比较运算符","slug":"比较运算符","link":"#比较运算符","children":[]},{"level":3,"title":"逻辑运算符","slug":"逻辑运算符","link":"#逻辑运算符","children":[]},{"level":3,"title":"向量匹配","slug":"向量匹配","link":"#向量匹配","children":[]},{"level":3,"title":"聚合运算","slug":"聚合运算","link":"#聚合运算","children":[]}]},{"level":2,"title":"容易误解的函数","slug":"容易误解的函数","link":"#容易误解的函数","children":[]},{"level":2,"title":"(965323899880.0 −965304237246.0) ÷ (1661570900.0 −1661570850.0) × 60 =","slug":"_965323899880-0-−965304237246-0-÷-1661570900-0-−1661570850-0-×-60","link":"#_965323899880-0-−965304237246-0-÷-1661570900-0-−1661570850-0-×-60","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"互动时刻","slug":"互动时刻","link":"#互动时刻","children":[]}],"relativePath":"运维监控系统实战笔记/06｜PromQL有哪些常见的使用场景？.md","filePath":"运维监控系统实战笔记/06｜PromQL有哪些常见的使用场景？.md","lastUpdated":1795561216000}'),p={name:"运维监控系统实战笔记/06｜PromQL有哪些常见的使用场景？.md"};function o(l,a,i,c,r,u){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_06-promql有哪些常见的使用场景" tabindex="-1">06 | PromQL有哪些常见的使用场景？ <a class="header-anchor" href="#_06-promql有哪些常见的使用场景" aria-label="Permalink to &quot;06 | PromQL有哪些常见的使用场景？&quot;">​</a></h1><p>你好，我是秦晓辉。</p><p>上一讲我们介绍了 Prometheus 中的一些关键设计，比如注重标准和生态、监控目标动态发现机制、PromQL 等，其中 PromQL 是 Prometheus 的查询语言，使用起来非常灵活方便，但很多人不知道如何更好地利用它，发挥不出它的优势。所以这一讲我们就来梳理一下 PromQL的典型应用场景。</p><p>PromQL 主要用于时序数据的查询和二次计算场景。我们先来回顾一下时序数据，在脑子里建立起时序数据的具象视图。</p><h2 id="时序数据" tabindex="-1">时序数据 <a class="header-anchor" href="#时序数据" aria-label="Permalink to &quot;时序数据&quot;">​</a></h2><p>我们可以把时序数据理解成一个以时间为轴的矩阵，你可以看一下我给出的例子，例子中有三个时间序列，在时间轴上分别对应不同的值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>^</span></span>
<span class="line"><span>│     . . . . . . . . . .   node_load1{host=&quot;host01&quot;,zone=&quot;bj&quot;}</span></span>
<span class="line"><span>│     . . . . . . . . . .   node_load1{host=&quot;host02&quot;,zone=&quot;sh&quot;}</span></span>
<span class="line"><span>│     . . . . . . . . . .   node_load1{host=&quot;host11&quot;,zone=&quot;sh&quot;}</span></span>
<span class="line"><span>v</span></span>
<span class="line"><span>&lt;------- 时间 ----------&gt;</span></span></code></pre></div><p>每一个点称为一个样本（sample），样本由三部分组成。</p><ul><li><p>指标（metric）：metric name 和描述当前样本特征的 labelsets。</p></li><li><p>时间戳（timestamp）：一个精确到毫秒的时间戳。</p></li><li><p>值（value）：表示该时间样本的值。</p></li></ul><p>PromQL 就是对这样一批样本数据做查询和计算操作。</p><h2 id="promql-典型的应用场景" tabindex="-1">PromQL 典型的应用场景 <a class="header-anchor" href="#promql-典型的应用场景" aria-label="Permalink to &quot;PromQL 典型的应用场景&quot;">​</a></h2><p>PromQL 典型的应用场景就是时序数据的查询和二次计算，这也是 PromQL 的两个核心价值，其中查询操作靠的就是查询选择器，下面我们就来详细地看一下。</p><h3 id="查询选择器" tabindex="-1">查询选择器 <a class="header-anchor" href="#查询选择器" aria-label="Permalink to &quot;查询选择器&quot;">​</a></h3><p>随便一个公司，时序数据至少都有成千上万条，而每个监控图表的渲染或者每条告警规则的处理，都只是针对有限的几条数据，所以 PromQL 第一个需求就是过滤。假设我有两个需求，一是查询上海所有机器 1 分钟的负载，二是查询所有以 host0 为前缀的机器 1 分钟的负载。PromQL 的写法是怎样的呢？你可以看一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 通过 = 来做 zone 的匹配过滤</span></span>
<span class="line"><span>node_load1{zone=&quot;sh&quot;}</span></span>
<span class="line"><span># 通过 =~ 来做 host 的正则过滤</span></span>
<span class="line"><span>node_load1{host=~&quot;host0.*&quot;}</span></span></code></pre></div><p>大括号里写过滤条件，主要是针对标签过滤，操作符除了等于号和正则匹配之外，还有不等于</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!= 和正则非 !~。这个比较容易理解，不过多介绍了。需要注意的是，metric name 也是一个</span></span></code></pre></div><p>非常重要的过滤条件，可以写到大括号里，比如我想同时查看上海机器的 load1、load5、</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>load15 三个指标，可以对 __name__，也就是 metric 名字做正则过滤。</span></span>
<span class="line"><span>{__name__=~&quot;node_load.*&quot;, zone=&quot;sh&quot;}</span></span></code></pre></div><p>上面的例子中，我给出的 3 条 PromQL 都叫做即时查询（Instant Query），返回的内容叫做即时向量（ Instant Vector）。</p><p>即时查询返回的是当前的最新值，比如 10 点整发起的查询，返回的就是 10 点整这一时刻对应的数据。但是监控数据是周期性上报的，并非每时每刻都有数据上报，10 点整的时候可能恰恰没有数据进来，此时 Prometheus 就会往前看，看看 9 点 59、9 点 58、9 点 57 等时间点有没有上报数据。最多往前看多久呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个数据由 Prometheus 的启动参数 --query.lookback-delta 控制，这个参数默认是  5</span></span>
<span class="line"><span>分钟。从监控的角度来看，我建议你调短一些，比如改成 1 分钟 --query.lookback-</span></span>
<span class="line"><span>delta=1m。为什么呢？</span></span></code></pre></div><p>我举个例子来说明一下，我们有个客户使用 Telegraf 做 HTTP 探测，配置了一个告警规则，说 response_code 连续 3 分钟都不等于 200 才告警。实际上只有一个数据点的response_code 不等于 200，过了 3 分钟还是报警了。他感觉非常困惑，就来问我为什么。</p><p>实际上，主要有两个原因，一是因为 Telegraf 的 HTTP 探测，会默认把 status code 放到标签里，这会导致标签非稳态结构（这个行为不太好，最好是把这类标签直接丢弃掉，或者使用categraf、blackbox_exporter 做采集器），平时 code=200，出问题的时候 code=500，在Prometheus 生态里，标签变了就是新的时间序列了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二个原因就跟 query.lookback-delta 有关了，虽然只有一个点异常，也就是说</span></span></code></pre></div><p>code=500 的这个时间序列只有一个点，但是告警规则每次执行查询的时候，都是查到这个异常点，连续 5 分钟都是如此。所以就满足了规则里连续 3 分钟才告警的这个条件，触发了告</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>警。这就是我建议你把 --query.lookback-delta 调短的原因。</span></span></code></pre></div><p>除了即时查询，PromQL 中还有一种查询，叫做范围查询（Range Query），返回的内容叫做Range Vector，比如下面的 PromQL。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{__name__=~&quot;node_load.*&quot;, zone=&quot;sh&quot;}[1m]</span></span></code></pre></div><p>相比即时查询，范围查询就是多加了一个时间范围 1 分钟。即时查询每个指标返回一个点，范围查询会返回多个点。假设数据 10 秒钟采集一次，1 分钟有 6 个点，都会返回。</p><p>Prometheus 官方文档在介绍各个函数的使用方法的时候，都会讲解函数参数，标明是Range Vector 还是 Instant Vector，这两种查询方式是基础知识，你需要牢牢掌握。</p><p>上面说的就是 PromQL 第一个核心价值——筛选。接下来我们看 PromQL 的另一个核心价值——计算。计算部分内容比较多，有算术、比较、逻辑、聚合运算符等，下面我们来一一看下。</p><h3 id="算术运算符" tabindex="-1">算术运算符 <a class="header-anchor" href="#算术运算符" aria-label="Permalink to &quot;算术运算符&quot;">​</a></h3><p>算术运算符比较简单，就是我们常用的加减乘除、取模之类的符号。这里我给出了两个例子，你可以结合这两个例子来了解它的应用场景。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 计算内存可用率，就是内存可用量除以内存总量，又希望按照百分比呈现，所以最后乘以100</span></span>
<span class="line"><span>mem_available{app=&quot;clickhouse&quot;} / mem_total{app=&quot;clickhouse&quot;} * 100</span></span>
<span class="line"><span># 计算北京区网口出向的速率，原始数据的单位是byte，网络流量单位一般用bit，所以乘以8</span></span>
<span class="line"><span>irate(net_sent_bytes_total{zone=&quot;beijing&quot;}[1m]) * 8</span></span></code></pre></div><h3 id="比较运算符" tabindex="-1">比较运算符 <a class="header-anchor" href="#比较运算符" aria-label="Permalink to &quot;比较运算符&quot;">​</a></h3><p>比较运算符就是大于、小于、等于、不等于之类的，理解起来也比较简单，但是意义重大，告警规则的逻辑就是靠比较运算符来支撑的。这里我也举两个例子，你结合例子来理解会更容易。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mem_available{app=&quot;clickhouse&quot;} / mem_total{app=&quot;clickhouse&quot;} * 100 &lt; 20</span></span>
<span class="line"><span>irate(net_sent_bytes_total{zone=&quot;beijing&quot;}[1m]) * 8 / 1024 / 1024 &gt; 700</span></span></code></pre></div><p>带有比较运算符的 PromQL 就是告警规则的核心，比如内存可用率的告警，在 Prometheus中可以这样配置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groups:</span></span>
<span class="line"><span>- name: host</span></span>
<span class="line"><span> rules:</span></span>
<span class="line"><span> - alert: MemUtil</span></span>
<span class="line"><span>   expr: mem_available{app=&quot;clickhouse&quot;} / mem_total{app=&quot;clickhouse&quot;} * 100 &lt; 2</span></span>
<span class="line"><span>   for: 1m</span></span>
<span class="line"><span>   labels:</span></span>
<span class="line"><span>     severity: warn</span></span>
<span class="line"><span>   annotations:</span></span>
<span class="line"><span>     summary: Mem available less than 20%, host:{​{ $labels.ident }​}</span></span></code></pre></div><p>例子中的 expr 指定了查询用的 PromQL。告警引擎会根据用户的配置，周期性地执行查询。如果查不到就说明一切正常，没有机器的内存可用率低于 20%。如果查到了，就说明触发了告警，查到几条就触发几条告警。当然，偶尔一次低于 20% 不是什么大事，只有连续 1 分钟</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次查询都低于 20% 才会告警，这就是 for: 1m 存在的意义。</span></span></code></pre></div><h3 id="逻辑运算符" tabindex="-1">逻辑运算符 <a class="header-anchor" href="#逻辑运算符" aria-label="Permalink to &quot;逻辑运算符&quot;">​</a></h3><p>逻辑运算符有 3 个，and、or 和 unless，用于 instant-vector 之间的运算。and 是求交集，or是求并集，unless 是求差集。我们来看一个 and 的使用场景。</p><p>关于磁盘的使用率问题，有的分区很大，比如 16T，有的分区很小，比如 50G，像这种情况如果只是用磁盘的使用率做告警就不太合理，比如</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>disk_used_percent{app=&quot;clickhouse&quot;} &gt; 70 表示磁盘使用率大于 70% 就告警。对</span></span></code></pre></div><p>于小盘，这个策略是合理的，但对于大盘，70% 的使用率表示还有非常多的空间，就不太合理。这时我们希望给这个策略加一个限制，只有小于 200G 的硬盘在使用率超过 70% 的时候，才需要告警，这时我们就可以使用 and 运算符，你可以看一下最终 PromQL。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>disk_used_percent{app=&quot;clickhouse&quot;} &gt; 70 and disk_total{app=&quot;clickhouse&quot;}/1024/10</span></span></code></pre></div><p>同理，or 和 unless 这两个逻辑运算符也是这样，你可以自己试一试。</p><p>算术、比较、逻辑运算符，基本的使用方式比较简单，但如果运算符两侧的向量标签不统一，就会面临一些更复杂的处理逻辑，需要在 PromQL 中给出向量匹配规则，下面我们就来一起看一下。</p><h3 id="向量匹配" tabindex="-1">向量匹配 <a class="header-anchor" href="#向量匹配" aria-label="Permalink to &quot;向量匹配&quot;">​</a></h3><p>向量之间的操作是想要在右侧的向量中，为左侧向量的每个条目找到一个匹配的元素，匹配行为分为：one-to-one、many-to-one、one-to-many。刚才介绍的磁盘使用率的例子，就是典型的 one-to-one 类型，左右两侧的指标，除了指标名，其余标签都是一样的，非常容易找到对应关系。但是有时候，我们希望用 and 求交集，但是两侧向量标签不同，怎么办呢？</p><p>此时我们可以使用关键字 on 和 ignoring 来限制用于做匹配的标签集。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql_slave_status_slave_sql_running == 0</span></span>
<span class="line"><span>and ON (instance)</span></span>
<span class="line"><span>mysql_slave_status_master_server_id &gt; 0</span></span></code></pre></div><p>这个 PromQL 想表达的意思是如果这个 MySQL 实例是个 slave（master_server_id&gt;0），就检查其 slave_sql_running 的值，如果 slave_sql_running==0，就表示 slave sql 线程没有在运行。</p><p>但 mysql_slave_status_slave_sql_running 和 mysql_slave_status_master_server_id 这两个metric 的标签，可能并非完全一致。不过好在二者都有个 instance 标签，且相同的 instance标签的数据从语义上来看就表示一个实例的多个指标数据，那我们就可以用关键字 on 来指定只使用 instance 标签做匹配，忽略其他标签。</p><p>与 on 相反的是关键字 ignoring，顾名思义，ignoring 是忽略掉某些标签，用剩下的标签来做匹配。我们拿 Prometheus 文档中的例子来说明。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## example series</span></span>
<span class="line"><span>method_code:http_errors:rate5m{method=&quot;get&quot;, code=&quot;500&quot;}  24</span></span>
<span class="line"><span>method_code:http_errors:rate5m{method=&quot;get&quot;, code=&quot;404&quot;}  30</span></span>
<span class="line"><span>method_code:http_errors:rate5m{method=&quot;put&quot;, code=&quot;501&quot;}  3</span></span>
<span class="line"><span>method_code:http_errors:rate5m{method=&quot;post&quot;, code=&quot;500&quot;} 6</span></span>
<span class="line"><span>method_code:http_errors:rate5m{method=&quot;post&quot;, code=&quot;404&quot;} 21</span></span>
<span class="line"><span>method:http_requests:rate5m{method=&quot;get&quot;}  600</span></span>
<span class="line"><span>method:http_requests:rate5m{method=&quot;del&quot;}  34</span></span>
<span class="line"><span>method:http_requests:rate5m{method=&quot;post&quot;} 120</span></span>
<span class="line"><span>## promql</span></span>
<span class="line"><span>method_code:http_errors:rate5m{code=&quot;500&quot;}</span></span>
<span class="line"><span>/ ignoring(code)</span></span>
<span class="line"><span>method:http_requests:rate5m</span></span>
<span class="line"><span>## result</span></span>
<span class="line"><span>{method=&quot;get&quot;}  0.04            //  24 / 600</span></span>
<span class="line"><span>{method=&quot;post&quot;} 0.05            //   6 / 120</span></span></code></pre></div><p>例子里都是 one-to-one 的对应关系，这个好理解。难理解的是 one-to-many 和 many-to-one，这种情况下，做指标运算时就要借助关键字 group_left 和 group_right 了。left、right指向高基数那一侧的向量。还是用上面 method_code:http_errors:rate5m 和method:http_requests:rate5m 这两个指标来举例，你可以看一下使用 group_left 的 PromQL和输出的结果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## promql</span></span>
<span class="line"><span>method_code:http_errors:rate5m</span></span>
<span class="line"><span>/ ignoring(code) group_left</span></span>
<span class="line"><span>method:http_requests:rate5m</span></span>
<span class="line"><span>## result</span></span>
<span class="line"><span>{method=&quot;get&quot;, code=&quot;500&quot;}  0.04            //  24 / 600</span></span>
<span class="line"><span>{method=&quot;get&quot;, code=&quot;404&quot;}  0.05            //  30 / 600</span></span>
<span class="line"><span>{method=&quot;post&quot;, code=&quot;500&quot;} 0.05            //   6 / 120</span></span>
<span class="line"><span>{method=&quot;post&quot;, code=&quot;404&quot;} 0.175           //  21 / 120</span></span>
<span class="line"><span>比如针对 method=&quot;get&quot; 的条目，右侧的向量中只有一个记录，但是左侧的向量中有两个记</span></span></code></pre></div><p>录，所以高基数的一侧是左侧，故而使用 group_left。</p><p>这里我再举一个例子，来说明 group_left、group_right 的一个常见用法。比如我们使用 kube-state-metrics 来采集 Kubernetes 各个对象的指标数据，其中针对 pod 有个指标是kube_pod_labels，该指标会把 pod 的一些信息放到标签里，指标值是 1，相当于一个元信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kube_pod_labels{</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span> label_name=&quot;frontdoor&quot;,</span></span>
<span class="line"><span> label_version=&quot;1.0.1&quot;,</span></span>
<span class="line"><span> label_team=&quot;blue&quot;</span></span>
<span class="line"><span> namespace=&quot;default&quot;,</span></span>
<span class="line"><span> pod=&quot;frontdoor-xxxxxxxxx-xxxxxx&quot;,</span></span>
<span class="line"><span>} = 1</span></span></code></pre></div><p>假设某个 Pod 是接入层的，统计了很多 HTTP 请求相关的指标，我们想统计 5xx 的请求数量，希望能按 Pod 的 version 画一个饼图。这里有个难点：接入层的请求类指标没有 version标签，version 信息只出现在 kube_pod_labels 里，那怎么让二者联动呢？</p><p>上答案！</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum(</span></span>
<span class="line"><span> rate(http_request_count{code=~&quot;^(?:5..)$&quot;}[5m])) by (pod)</span></span>
<span class="line"><span>*</span></span>
<span class="line"><span>on (pod) group_left(label_version) kube_pod_labels</span></span></code></pre></div><p>我们把这个 PromQL 掰开揉碎，看一下具体的意思，乘号前面的部分，是一个统计每秒 5xx数量的典型语法，按照 pod 维度做分组统计。</p><p>然后我们乘以 kube_pod_labels，这个值是 1。任何值乘以 1 都是原来的值，所以对整体数值没有影响，而 kube_pod_labels 有多个标签，而且和 sum 语句的结果向量的标签不一致，所以通过 on(pod) 语法来指定只按照 pod 标签来建立对应关系。</p><p>最后，利用 group_left(label_version)，把 label_version 附加到了结果向量里，高基数的部分显然是 sum 的部分，所以使用 group_left 而非 group_right。</p><h3 id="聚合运算" tabindex="-1">聚合运算 <a class="header-anchor" href="#聚合运算" aria-label="Permalink to &quot;聚合运算&quot;">​</a></h3><p>除了前面我们说的查询需求外，针对单个指标的多个 series，还会有一些聚合需求。比如说，我想查看 100 台机器的平均内存可用率，或者想要排个序，取数值最小的 10 台。这种需求可以使用 PromQL 内置的聚合函数来实现。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 求取 clickhouse 的机器的平均内存可用率</span></span>
<span class="line"><span>avg(mem_available_percent{app=&quot;clickhouse&quot;})</span></span>
<span class="line"><span># 把 clickhouse 的机器的内存可用率排个序，取最小的两条记录</span></span>
<span class="line"><span>bottomk(2, mem_available_percent{app=&quot;clickhouse&quot;})</span></span></code></pre></div><p>另外，我们有时会有分组统计的需求，比如我想分别统计 clickhouse 和 canal 的机器内存可用率，可以使用关键字 by 指定分组统计的维度（与 by 相反的是 without）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>avg(mem available percent{app=~&quot;clickhouse|canal&quot;}) by (app)</span></span></code></pre></div><p>注意：这些聚合运算，可以理解为纵向拟合。你可以想象一下，100 台机器的内存可用率，在折线图上有 100 条线，如果我们想要把这 100 条线拟合成一条线，就相当于把每个时刻的100 个点拟合成 1 个点。那怎么让 100 个点变成 1 个点呢？求个平均值或最大值之类的，就可以实现，所以就有了这些聚合运算符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>还有一类聚合运算函数，可以看作是横向拟合，也就是 &lt;​aggregation&gt;_over_time 类的</span></span>
<span class="line"><span>函数。这些函数接收范围向量，因为范围向量是一个时段内有多个值，&lt;​aggregation&gt; 就</span></span></code></pre></div><p>是对这多个值做运算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>max_over_time(target_up[2m])</span></span></code></pre></div><p>target_up 指标后面加了 [2m]，指的就是获取这个指标最近 2 分钟的所有数据点，如果 15 秒采集一个点，2 分钟就是 8 个点，max_over_time 就是对这 8 个点求最大值，相当于对各个时间序列做横向拟合。</p><h2 id="容易误解的函数" tabindex="-1">容易误解的函数 <a class="header-anchor" href="#容易误解的函数" aria-label="Permalink to &quot;容易误解的函数&quot;">​</a></h2><p>除了上面我们说的这些常用的聚合函数外，Prometheus 还内置了很多其他函数，其中用得最广并且最容易被人误解的是 increase 和 rate 函数，我们讲一讲这两个函数。</p><p>先来看 increase 函数，字面意思上表示求取一个增量，接收一个 range-vector，range-vector显然是会返回多个 value+timestamp 的组合。我们直观地理解就是，直接把时间范围内的最后一个值减去第一个值，不就可以得到增量了吗？非也！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/1.png" alt=""></a></p><p>你可以看一下这张图，图里的一些关键信息，我摘录成了文本，你可以看一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>promql: net_bytes_recv{interface=&quot;eth0&quot;}[1m] @ 1661570908</span></span>
<span class="line"><span>965304237246 @1661570850</span></span>
<span class="line"><span>965307953982 @1661570860</span></span>
<span class="line"><span>965311949925 @1661570870</span></span>
<span class="line"><span>965315732812 @1661570880</span></span>
<span class="line"><span>965319998347 @1661570890</span></span>
<span class="line"><span>965323899880 @1661570900</span></span>
<span class="line"><span>promql: increase(net_bytes_recv{interface=&quot;eth0&quot;}[1m]) @1661570909</span></span>
<span class="line"><span>23595160.8</span></span></code></pre></div><p>监控数据是 10 秒上报一次，所以虽然两次 PromQL 查询时间不同，一次是 1661570908，一次是 1661570909，但是所查询的原始数据内容是一样的，就是 1661570850~1661570900 这几个时间点对应的数据。</p><p>直观上理解，在这几个时间点对应的数据上求取 increase，无非就是最后一个值减去第一个值，即 965323899880-965304237246=19662634。不过很遗憾，实际结果是 23595160.8，差别有点大，显然这个直观理解的算法是错的。</p><p>实际上，increase 这个 PromQL 发起请求的时间是 1661570909，时间范围是[1m]，相当于告诉 Prometheus，我要查询 1661570849（由 1661570909-60 得出）~1661570909 之间的increase 数值。但是原始监控数据并没有 1661570849、1661570909 这两个时刻的数值，怎么办呢？</p><p>Prometheus 只能基于现有的数据做外推，也就是使用最后一个点的数值减去第一个点的数值，得到的结果除以时间差，再乘以 60。</p><h2 id="_965323899880-0-−965304237246-0-÷-1661570900-0-−1661570850-0-×-60" tabindex="-1">(965323899880.0 −965304237246.0) ÷ (1661570900.0 −1661570850.0) × 60 = <a class="header-anchor" href="#_965323899880-0-−965304237246-0-÷-1661570900-0-−1661570850-0-×-60" aria-label="Permalink to &quot;(965323899880.0 −965304237246.0) ÷ (1661570900.0 −1661570850.0) × 60 =&quot;">​</a></h2><p>这样最终就得到了 1 分钟的 increase 值，是个小数。趁热打铁，我们再说一下 rate 函数，increase 函数是求取的时间段内的增量，而且有数据外推，rate 函数则求取的是每秒变化率，也有数据外推的逻辑，increase 的结果除以 range-vector 的时间段的大小，就是 rate 的值。我们用下面的 PromQL 验证一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rate(net_bytes_recv{interface=&quot;eth0&quot;}[1m])</span></span>
<span class="line"><span>== bool</span></span>
<span class="line"><span>increase(net_bytes_recv{interface=&quot;eth0&quot;}[1m])/60.0</span></span></code></pre></div><p>这里 == 后面跟了一个 bool 修饰符，表示希望返回一个 bool 值，如果是 True 就会返回 1，如果是 False 就返回 0。我们观察结果后发现，这个表达式永远都会返回 1，即等号前后的两个PromQL 语义上是相同的。</p><p>rate 函数求取的变化率，相对平滑。因为是拿时间范围内的最后一个值和第一个值做数据外推，一些毛刺现象就会被平滑掉。如果想要得到更敏感的数据，我们可以使用 irate 函数。irate 是拿时间范围内的最后两个值来做计算，变化就会更剧烈，我们拿网卡入向流量这个指标来做个对比。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/2.png" alt=""></a></p><p>蓝色的变化得更剧烈的线是用 irate 函数计算得到的，而紫色的相对平滑的线是用 rate 函数计算得到的，对比还是很强烈的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲我们以实际场景为出发点，介绍了不同场景下如何使用 PromQL。为了让你更好地理解，我们回顾了时序数据的内容，你需要在脑海里建立一个时序数据的二维图像，方便你之后理解和使用 PromQL。</p><p>我们还重点讲解了 PromQL 的两个核心价值，一个是筛选，一个是计算。筛选是靠查询选择器，查询分为即时查询和范围查询。计算部分内容较多，有算术、比较、逻辑、聚合运算符，还有向量匹配逻辑，特别是 group_left 和 group_right，比较难理解，需要你仔细推敲。</p><p>函数部分比较重要的是 increase 和 rate，其实 histogram_quantile 也很常用而且比较难理解，不过我们在前面的第 2 讲中已经介绍过 histogram_quantile 的计算逻辑了，这里就不再重复。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/06/3.png" alt=""></a></p><h2 id="互动时刻" tabindex="-1">互动时刻 <a class="header-anchor" href="#互动时刻" aria-label="Permalink to &quot;互动时刻&quot;">​</a></h2><p>Prometheus 中提供了一个函数叫 absent，用于做数据缺失告警，使用得也很广泛，但是坑也挺大。这里我留给你一个问题：如果我想对 100 台机器的 node_load1 做数据缺失告警，应该如何配置？这个需求用 absent 解决合适吗？你能否给出 absent 的最佳使用场景？</p><p>欢迎留言讨论，也欢迎你把今天的内容分享给你身边的朋友，邀他一起学习。我们下一讲再见！</p>`,104)])])}const m=s(p,[["render",o]]);export{h as __pageData,m as default};
